def max_energy(beads):
    # Initialize a dictionary to store the maximum energy obtainable from each bead
    max_energy_from_bead = {i: 0 for i in range(len(beads))}
    # Iterate over the beads in reverse order
    for i in range(len(beads) - 1, -1, -1):
        # Get the head value of the current bead
        head = beads[i]
        # Find the next bead with the same tail value as the current bead's head
        next_bead = i + 1
        if next_bead == len(beads):
            next_bead = 0
        while next_bead != i:
            tail = beads[next_bead]
            # Calculate the energy release from merging the current bead with the next bead
            energy = head * tail * beads[next_bead + 1]
            # Update the maximum energy obtainable from the current bead
            max_energy_from_bead[i] = max(max_energy_from_bead[i], energy)
            # Move to the next bead with the same tail value as the current bead's head
            next_bead += 1
            if next_bead == len(beads):
                next_bead = 0
    # Return the maximum energy obtainable by optimally merging all beads
    return max(max_energy_from_bead.values())

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_term(coeff: int, degree: int) -> str:
        if coeff == 0:
            return ""
        sign = "+" if coeff > 0 else "-"
        abs_coeff = abs(coeff)
        if degree > 1 and abs_coeff == 1:
            coeff_str = "x"
        else:
            coeff_str = str(abs_coeff)
        if degree == 0:
            return coeff_str
        elif degree == 1:
            return f"{sign}{coeff_str}x"
        else:
            return f"{sign}{coeff_str}x^{degree}"

    terms = [format_term(coeff, degree) for degree, coeff in enumerate(coeffs)]
    return "".join(term for term in terms if term)

