                dp[i][j] = max(dp[i][j-1], dp[i-volumes[j-1]][j-1] + volumes[j-1])
            else:
                dp[i][j] = dp[i][j-1]

    # The minimum remaining space is the difference between the box's
    # total capacity and the maximum occupied volume
    return V - dp[V][n]

